> +static int tegra_vpr_debugfs_show(struct seq_file *s, struct dma_heap *heap)
> +{
> +	struct tegra_vpr *vpr = dma_heap_get_drvdata(heap);
> +	phys_addr_t limit = vpr->base + vpr->size;
> +	char buf[16];
