index b315c608f..9e3e005a8 100644
--- a/net/netfilter/ipvs/ip_vs_ftp.c
+++ b/net/netfilter/ipvs/ip_vs_ftp.c
@@ -102,7 +102,7 @@ static int ip_vs_ftp_get_addrport(char *data, char
*data_limit,
  char *s, c;
  unsigned char p[6];
  char edelim;
- __u16 hport;
+ __u32 hport;
  int i = 0;

  if (data_limit - data < plen) {
@@ -144,7 +144,11 @@ static int ip_vs_ftp_get_addrport(char *data,
char *data_limit,
  return -1;
  c = *data;
  if (isdigit(c)) {
- p[i] = p[i]*10 + c - '0';
+ unsigned int val = p[i] * 10 + c - '0';
+
+ if (val > 255)
+ return -1;
+ p[i] = val;
  } else if (c == ',' && i < 5) {
  i++;
  p[i] = 0;
@@ -222,6 +226,8 @@ static int ip_vs_ftp_get_addrport(char *data, char
*data_limit,
  if (!isdigit(*s))
  break;
  hport = hport * 10 + *s - '0';
+ if (hport > 65535)
+ return -1;
  }
  if (s == data_limit || !hport || *s != edelim)
