+			st->data.d8[1] = LTC2499_EN2 | LTC2499_IM;
+		} else {
+			st->data.d8[0] = LTC2497_ENABLE | address;
+			st->data.d8[1] = LTC2499_EN2;
+		}
+
+		ret = i2c_master_send(st->client, (char *)st->data.d8, 2);
+		if (ret < 0) {
+			dev_err(&st->client->dev, "i2c transfer failed: %pe\n",
+				ERR_PTR(ret));
+			return ret;
+		}
+		return 0;
+	}
+
